DELETED = 0

    AND ENTERPRISE_ID = #{enterpriseId}


    AND ENTERPRISE_NAME LIKE CONCAT('%', #{enterpriseName}, '%')


    AND MONITORING_TYPE = #{monitoringType}


    AND MONITORING_STATUS = #{monitoringStatus}


    AND ALERT_STATUS = #{alertStatus}


    AND MONITORING_NAME LIKE CONCAT('%', #{monitoringName}, '%')


    AND START_TIME >= #{startDate}


    AND START_TIME <= #{endDate}

mapper.select:
SELECT LAST_UPDATE_TIME as updateTime, CURRENT_VALUE as value, ALERT_STATUS as alertStatus, CASE WHEN ALERT_STATUS = 'DANGER' THEN 1 WHEN ALERT_STATUS = 'WARNING' THEN 0.5 ELSE 0 END as anomalyScore FROM TBL_RISK_MONITORING WHERE RISK_MONITORING_ID = #{riskMonitoringId} AND DELETED = 0
AND LAST_UPDATE_TIME >= #{startDate}
AND LAST_UPDATE_TIME <= #{endDate}
ORDER BY LAST_UPDATE_TIME DESC
LIMIT 1000
OFFSET 0 ROWS FETCH NEXT 1000 ROWS ONLY
